-- 009_import_algerie_poste_dz_osm.sql
-- Fusion additive : import des DAB Algerie Poste (Algérie) présents en
-- local mais absents de la prod (aucun DAB Algerie Poste existant à moins
-- de 150m). Comparaison faite le 2026-09-23 entre les 1474 DAB Algerie
-- Poste locaux et les 187 alors en prod (post-nettoyage migration 008).
-- Source d'origine (osm/google_places/admin/communaute) préservée par ligne.
--
-- Additif uniquement : ne touche à aucune ligne existante. ON CONFLICT sur
-- osm_id (contrainte UNIQUE) rend l'opération idempotente si rejouée sur un
-- environnement qui a déjà ces lignes (ex: le local, source de ces données).
--
-- banque_id résolu par nom (pas par id, qui diffère entre environnements).

ON CONFLICT (osm_id) DO NOTHING;
